-- School Financial Reports widget (Vanessa and Sean, 2026-11-16). OptiSchool no longer
-- serves these, so school WCMs had no way to get their latest report. Source: the two
-- finance PDFs (2023-2024_FNC1712S.pdf, 2024-2025_FNC1712_v2.pdf), one page per school,
-- split into one PDF per school and year (public/financial-reports/<year>/<loc>.pdf).
-- 2024-25 has a scrambled Type3 font, so location numbers were decoded from glyph shapes
-- and names OCR-checked against the page image (475 of 475 files match their header).
-- Left out: a repeated Broward Virtual Franchise page and the "Expense Override Records
-- Changed 0" system stub at the end of each PDF. Public read, edits through
-- /api/bcps/school-financial-reports (service role, ACL-gated).

CREATE TABLE IF NOT EXISTS public.bcps_school_financial_reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  location_number text NOT NULL,
  school_name text NOT NULL,
  school_year text NOT NULL,
  file_url text NOT NULL,
  file_name text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (location_number, school_year)
);

ALTER TABLE public.bcps_school_financial_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public read school financial reports" ON public.bcps_school_financial_reports FOR SELECT TO anon, authenticated USING (true);
REVOKE ALL ON public.bcps_school_financial_reports FROM anon, authenticated;
GRANT SELECT (id, location_number, school_name, school_year, file_url, file_name) ON public.bcps_school_financial_reports TO anon, authenticated;

ON CONFLICT (location_number, school_year) DO NOTHING;
